<template><div class="app-container"><el-form :inline="true" size="small" :model="query"><el-form-item label="SKU 编码"><el-input v-model="query.skuCode" clearable/></el-form-item><el-form-item><el-checkbox v-model="query.lowStockOnly">仅看低库存</el-checkbox></el-form-item><el-form-item><el-button type="primary" icon="el-icon-search" size="mini" @click="load">查询</el-button></el-form-item></el-form><el-table v-loading="loading" :data="list"><el-table-column prop="skuId" label="SKU ID" width="90"/><el-table-column prop="skuCode" label="SKU 编码"/><el-table-column prop="skuName" label="SKU 名称"/><el-table-column prop="availableQuantity" label="可用库存" width="100"/><el-table-column prop="lockedQuantity" label="锁定库存" width="100"/><el-table-column prop="soldQuantity" label="已售数量" width="100"/><el-table-column prop="warningThreshold" label="预警阈值" width="100"/><el-table-column label="操作" width="180"><template slot-scope="s"><el-button type="text" size="mini" icon="el-icon-edit" @click="openAdjust(s.row)" v-hasPermi="['mall:inventory:adjust']">调整库存</el-button><el-button type="text" size="mini" icon="el-icon-tickets" @click="showLogs(s.row)">流水</el-button></template></el-table-column></el-table><pagination v-show="total > 0" :total="total" :page.sync="query.pageNum" :limit.sync="query.pageSize" @pagination="load"/><el-dialog title="调整库存" :visible.sync="dialog" width="420px"><el-form :model="adjustForm" label-width="90px"><el-form-item label="调整数量"><el-input-number v-model="adjustForm.quantity"/></el-form-item><el-form-item label="调整原因"><el-input v-model="adjustForm.reason" type="textarea"/></el-form-item></el-form><div slot="footer"><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="saveAdjust">确定</el-button></div></el-dialog><el-dialog title="库存流水" :visible.sync="logsDialog" width="850px"><el-table :data="logs"><el-table-column prop="operationType" label="操作类型"/><el-table-column prop="availableChange" label="可用变更"/><el-table-column prop="lockedChange" label="锁定变更"/><el-table-column prop="soldChange" label="已售变更"/><el-table-column prop="reason" label="原因"/><el-table-column prop="operator" label="操作人"/><el-table-column prop="createTime" label="时间"/></el-table></el-dialog></div></template>
<script>import { listStocks, listStockLogs, adjustStock } from '@/api/mall/inventory'
export default { name: 'MallInventory', data () { return { loading: false, list: [], total: 0, query: { pageNum: 1, pageSize: 10, lowStockOnly: false }, dialog: false, logsDialog: false, adjustForm: {}, logs: [] } }, created () { this.load() }, methods: { load () { this.loading = true; const q = Object.assign({}, this.query, { lowStockOnly: this.query.lowStockOnly }); listStocks(q).then(r => { const d = r.data || r; this.list = d.rows || (Array.isArray(d) ? d : []); this.total = d.total || this.list.length }).finally(() => { this.loading = false }) }, openAdjust (r) { this.adjustForm = { skuId: r.skuId, delta: 0, reason: '' }; this.dialog = true }, saveAdjust () { adjustStock(this.adjustForm.skuId, { delta: this.adjustForm.delta, reason: this.adjustForm.reason }).then(() => { this.$modal.msgSuccess('库存已调整'); this.dialog = false; this.load() }) }, showLogs (r) { listStockLogs(r.skuId).then(x => { this.logs = x.data || []; this.logsDialog = true }) } } }</script>
